
const login = "noize_mc"
export const TG = {
  links: {
    desktop: `tg://resolve?domain=${login}`,
    mobile: `https://t.me/${login}`
  },
  get link() {
    const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    return isMobile ? this.links.mobile : this.links.desktop;
  },
};

const botLogin = "HowToNormalnoBot"

export const BOT = {
  links: {
    desktop: `tg://resolve?domain=${botLogin}`,
    mobile: `https://t.me/${botLogin}`
  },
  startProps: {
    mentoring: 'mentoring',
    club: 'club'
  }
};


export const getLink = (startProp) => {
  const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
  let link = isMobile ? BOT.links.mobile : BOT.links.desktop;
  if (startProp) {
    const prefix = isMobile ? `?` : `&`
    link = link + prefix + `start=${startProp}`
  }
  return link
}

